"""Invertible padding with colliding alphabets and explicit alignment accounting."""
import math
import random

MARKERS = "bd"
SCHEMES = ("constant", "alternating", "permuted", "suffix-forward", "suffix-reverse")


def patterns(source, scheme, seed=None):
    if scheme in ("suffix-forward", "suffix-reverse"):
        result = []
        for i, word in enumerate(source.split(" ")):
            if i:
                result.append(("S", " "))
            result.extend(("S", c) for c in word)
            result.extend((("M", "b"), ("M", "d")))
        return result[::-1] if scheme == "suffix-reverse" else result

    markers = ["b" if scheme == "constant" or (ord(c) - ord("a")) % 2 else "d"
               for c in source if c != " "]
    if scheme == "permuted":
        random.Random(seed).shuffle(markers)
    markers = iter(markers)
    result = []
    for c in source:
        result.append(("S", c))
        if c != " ":
            result.append(("M", next(markers)))
    return result


def machine(scheme, schedule=None):
    """Yield current role and any forced glyph. Receive the next emitted glyph."""
    if scheme == "suffix-forward":
        for i, length in enumerate(schedule):
            if i:
                forced = yield "S", " "
                assert forced == " "
            for _ in range(length):
                yield "S", None
            for _ in range(2):
                yield "M", None
    elif scheme == "suffix-reverse":
        while True:
            for _ in range(2):
                yield "M", None
            while (yield "S", None) != " ":
                pass
    else:
        while True:
            c = yield "S", None
            if c != " ":
                yield "M", None


def numeric_schedule(source):
    return [len(w) for w in source.split(" ")]


def collect(events, scheme):
    if scheme == "suffix-reverse":
        events = events[::-1]
    return "".join(c for state, c in events if state == "S"), "".join(c for _, c in events)


def varint(number):
    assert number >= 0
    data = bytearray()
    while number >= 128:
        data.append((number & 127) | 128)
        number >>= 7
    data.append(number)
    return bytes(data)


def read_varints(blob):
    value = bits = 0
    for byte in blob:
        value += (byte & 127) << bits
        if byte < 128:
            yield value
            value = bits = 0
        else:
            bits += 7
    assert bits == 0


def schedule_bytes(blocks):
    data = bytearray()
    for source in blocks:
        counts = numeric_schedule(source)
        data.extend(varint(len(counts)))
        for n in counts:
            data.extend(varint(n))
    return bytes(data)


def decode_schedule(data, count):
    values = iter(read_varints(data))
    rows = [[next(values) for _ in range(next(values))] for _ in range(count)]
    assert next(values, None) is None
    assert all(x >= 1 for row in rows for x in row)
    return rows


def marker_rank(markers, k):
    """Rank an ordered binary marker vector among all vectors with k d's."""
    left = len(markers)
    ways = math.comb(left, k)
    nbits = (ways - 1).bit_length()
    rank = 0
    for marker in markers:
        zero_first = ways * (left - k) // left
        if marker == "b":
            ways = zero_first
        else:
            rank += zero_first
            ways -= zero_first
            k -= 1
        left -= 1
    assert not k and ways == 1
    return rank, nbits


def marker_unrank(length, k, rank):
    ways = math.comb(length, k)
    assert 0 <= rank < ways
    markers = []
    for left in range(length, 0, -1):
        zero_first = ways * (left - k) // left
        if rank < zero_first:
            markers.append("b")
            ways = zero_first
        else:
            markers.append("d")
            rank -= zero_first
            ways -= zero_first
            k -= 1
    assert rank == k == 0
    return markers


def pack_random(blocks, padded_events):
    code = length = 0
    for source, sequence in zip(blocks, padded_events):
        markers = [c for state, c in sequence if state == "M"]
        count_d = sum((ord(c) - ord("a")) % 2 == 0 for c in source if c != " ")
        rank, width = marker_rank(markers, count_d)
        code = (code << width) | rank
        length += width
    pad = -length % 8
    return (code << pad).to_bytes((length + pad) // 8, "big"), length


def unpack_random(blocks, data, length):
    pad = -length % 8
    code = int.from_bytes(data, "big") >> pad
    remaining = length
    outputs = []
    for source in blocks:
        n = sum(c != " " for c in source)
        k = sum((ord(c) - ord("a")) % 2 == 0 for c in source if c != " ")
        width = (math.comb(n, k) - 1).bit_length()
        remaining -= width
        rank = (code >> remaining) & ((1 << width) - 1)
        markers = iter(marker_unrank(n, k, rank))
        outputs.append("".join(c + (next(markers) if c != " " else "") for c in source))
    assert remaining == 0
    return outputs

