"""Self-contained packets for matched finite-context padding comparisons."""
from collections import Counter, defaultdict
from functools import lru_cache
import json
import math
import struct
import zlib

from arith import Decoder, Encoder
from padding import (
    MARKERS, collect, decode_schedule, machine, numeric_schedule, pack_random,
    patterns, schedule_bytes, unpack_random,
)

SOURCE = " abcdefghijklmnopqrstuvwxyz"
TOTAL = 32768
MASS = 2
BASE = 0.5
HEADER = struct.Struct(">4sIII")


class History:
    def __init__(self, maximum, mode):
        self.maximum = maximum
        self.mode = mode
        self.chars = []
        self.sources = []

    def add(self, role, sym):
        if role == "S":
            self.sources.append(len(self.chars))
        self.chars.append(sym)

    def contexts(self):
        if self.mode == "output":
            return tuple("".join(self.chars[-n:]) for n in range(1, self.maximum + 1))
        return tuple("".join(self.chars[self.sources[-n]:]) if len(self.sources) >= n
                     else "".join(self.chars) for n in range(1, self.maximum + 1))


class Model:
    def __init__(self, order, mode, alphabets, tables=None):
        self.order = order
        self.mode = mode
        self.alphabets = alphabets
        self.tables = tables if tables is not None else {
            symbol: [defaultdict(Counter) for _ in range(order + 1)]
            for symbol in alphabets
        }
        self.symbol_index = {r: {s: i for i, s in enumerate(a)} for r, a in alphabets.items()}

    def properties(self):
        return {"order": self.order, "mode": self.mode, "alphabet": self.alphabets,
                "total": TOTAL, "mass": MASS, "base": BASE}

    def state_data(self):
        data = json.dumps(self.tables, separators=(",", ":"), sort_keys=True)
        return zlib.compress(data.encode(), 9)

    def history(self):
        return History(self.order, self.mode)

    def fit(self, streams, forced_spaces=False):
        for sequence in streams:
            recent = self.history()
            for role, sym in sequence:
                if not (forced_spaces and role == "S" and sym == " "):
                    for table, context in zip(self.tables[role], ("", *recent.contexts())):
                        table[context][sym] += 1
                recent.add(role, sym)
        return self

    @lru_cache(maxsize=32768)
    def prediction_path(self, role, contexts):
        alphabet = self.alphabets[role]
        base_counts = self.tables[role][0].get("", {})
        z = sum(base_counts.values()) + BASE * len(alphabet)
        probs = [(base_counts.get(c, 0) + BASE) / z for c in alphabet]
        path = [probs]
        for table, ctx in zip(self.tables[role][1:], contexts):
            counts = table.get(ctx)
            if counts:
                scale = sum(counts.values()) + MASS
                probs = [(counts.get(c, 0) + MASS * p) / scale for c, p in zip(alphabet, probs)]
            path.append(probs)
        return path

    @lru_cache(maxsize=32768)
    def cdf(self, role, contexts):
        prob = self.prediction_path(role, contexts)[-1]
        k = len(prob)
        shares = [p * (TOTAL - k) for p in prob]
        counts = [int(x) + 1 for x in shares]
        remaining = TOTAL - sum(counts)
        assert 0 <= remaining <= k
        order = sorted(range(k), key=lambda i: (int(shares[i]) - shares[i], i))
        for i in order[:remaining]:
            counts[i] += 1
        cumulative = [0]
        for count in counts:
            cumulative.append(cumulative[-1] + count)
        return cumulative

    def ideal_path(self, streams, forced_spaces=False):
        totals = [0.0] * (self.order + 1)
        for sequence in streams:
            history = self.history()
            for role, sym in sequence:
                if not (forced_spaces and role == "S" and sym == " "):
                    j = self.symbol_index[role][sym]
                    probabilities = self.prediction_path(role, history.contexts())
                    for i, probs in enumerate(probabilities):
                        totals[i] -= math.log2(probs[j])
                history.add(role, sym)
        return totals


def make_encoding(blocks, padded, model, route, scheme):
    encoder = Encoder()
    side = b""
    side_bits = 0
    if route == "inverse":
        streams = [[("S", c) for c in b] for b in blocks]
        if scheme == "permuted":
            side, side_bits = pack_random(blocks, padded)
    else:
        streams = padded
        if scheme == "suffix-forward":
            side = schedule_bytes(blocks)
            side_bits = 8 * len(side)
    forced_spaces = route != "inverse" and scheme == "suffix-forward"
    quantized_bits = 0.0
    for sequence in streams:
        history = model.history()
        for role, char in sequence:
            if not (forced_spaces and role == "S" and char == " "):
                table = model.cdf(role, history.contexts())
                symbol = model.symbol_index[role][char]
                encoder.write(table, symbol)
                quantized_bits -= math.log2((table[symbol + 1] - table[symbol]) / TOTAL)
            history.add(role, char)
    payload, nbits = encoder.finish()
    parameters = {
        "model": model.properties(),
        "scheme": scheme,
        "route": route,
        "source_lengths": list(map(len, blocks)),
        "coded_stream_lengths": list(map(len, streams)),
        "payload_bits": nbits,
        "side_bits": side_bits,
    }
    descriptors = json.dumps(parameters, sort_keys=True, separators=(",", ":")).encode()
    model_blob = model.state_data()
    frame = HEADER.pack(b"VPC1", len(descriptors), len(model_blob), len(side))
    packet = frame + descriptors + model_blob + side + payload
    stats = {
        "quantized_logloss_bits": quantized_bits,
        "arithmetic_emitted_bits": nbits,
        "arithmetic_padded_bits": 8 * len(payload),
        "model_bits": 8 * len(model_blob),
        "header_bits": 8 * (len(frame) + len(descriptors)),
        "side_bits": side_bits,
        "side_padded_bits": 8 * len(side),
        "packet_bits": 8 * len(packet),
        "symbol_counts": {"original": sum(map(len, blocks)), "emitted": sum(map(len, padded)),
                          "coded_or_forced_events": sum(map(len, streams))},
    }
    assert abs(quantized_bits - nbits) < 2.1
    assert sum(stats[k] for k in ("arithmetic_padded_bits", "model_bits", "header_bits", "side_padded_bits")) == stats["packet_bits"]
    return packet, stats


def decode(packet):
    name, header_length, model_length, side_length = HEADER.unpack_from(packet)
    assert name == b"VPC1"
    start = HEADER.size
    meta = json.loads(packet[start:start + header_length])
    start += header_length
    counts = json.loads(zlib.decompress(packet[start:start + model_length]))
    start += model_length
    side = packet[start:start + side_length]
    start += side_length
    payload = packet[start:]
    assert len(payload) == (meta["payload_bits"] + 7) // 8
    m = meta["model"]
    assert (m["total"], m["mass"], m["base"]) == (TOTAL, MASS, BASE)
    model = Model(m["order"], m["mode"], m["alphabet"], counts)
    decoder = Decoder(payload)
    route, scheme = meta["route"], meta["scheme"]
    lengths = meta["coded_stream_lengths"]
    if scheme == "suffix-forward" and route != "inverse":
        schedules = decode_schedule(side, len(lengths))
    else:
        schedules = [None] * len(lengths)
    original, padded = [], []
    for size, schedule in zip(lengths, schedules):
        recent = model.history()
        switch = machine(scheme, schedule) if route != "inverse" else None
        current = next(switch) if switch is not None else ("S", None)
        events = []
        for t in range(size):
            role, forced = current
            if forced is not None:
                char = forced
            else:
                symbol = decoder.read(model.cdf(role, recent.contexts()))
                char = model.alphabets[role][symbol]
            recent.add(role, char)
            events.append((role, char))
            if switch is not None and t + 1 < size:
                current = switch.send(char)
        if route == "inverse":
            original.append("".join(c for _, c in events))
        else:
            direct, expanded = collect(events, scheme)
            original.append(direct)
            padded.append(expanded)
    assert list(map(len, original)) == meta["source_lengths"]
    if route == "inverse":
        if scheme == "permuted":
            padded = unpack_random(original, side, meta["side_bits"])
        else:
            padded = [collect(patterns(b, scheme), scheme)[1] for b in original]
    return original, padded
